import{_ as t,c as a,o as i,ag as o}from"./chunks/framework.DzTbpWAc.js";const h=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md"}'),r={name:"api/index.md"};function c(l,e,d,n,s,p){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>This section provides detailed documentation for all the functions and types exported by the <code>reactive-proxy-state</code> library.</p><h2 id="core-apis" tabindex="-1">Core APIs <a class="header-anchor" href="#core-apis" aria-label="Permalink to &quot;Core APIs&quot;">​</a></h2><ul><li><a href="/reactive-proxy-state/api/reactive.html"><code>reactive</code></a> - Create reactive proxy objects</li><li><a href="/reactive-proxy-state/api/ref.html"><code>ref</code></a> - Create reactive references for primitive values</li><li><a href="/reactive-proxy-state/api/computed.html"><code>computed</code></a> - Create derived reactive state</li><li><a href="/reactive-proxy-state/api/watch-effect.html"><code>watchEffect</code></a> - Run and automatically re-run functions when dependencies change</li><li><a href="/reactive-proxy-state/api/watch.html"><code>watch</code></a> - Watch specific reactive sources for changes</li><li><a href="/reactive-proxy-state/api/update-state.html"><code>updateState</code></a> - Apply state change events to objects</li><li><a href="/reactive-proxy-state/api/mark-raw.html"><code>markRaw</code></a> - Flag an object so it is never made reactive</li></ul><h2 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h2><ul><li><a href="/reactive-proxy-state/api/vue3.html"><code>trackVueReactiveEvents</code></a> - Emit RPS StateEvents from Vue 3 reactivity</li><li><a href="/reactive-proxy-state/api/electron-bridge.html"><code>Electron Bridge</code></a> - Loop-safe bi-directional sync for Electron</li></ul><h2 id="helper-functions" tabindex="-1">Helper Functions <a class="header-anchor" href="#helper-functions" aria-label="Permalink to &quot;Helper Functions&quot;">​</a></h2><ul><li><code>isRef</code> - Check if a value is a ref object</li><li><code>unref</code> - Unwrap a ref to get its inner value</li><li><code>toRefs</code> - Convert reactive object properties to individual refs</li><li><code>isReactive</code> - Check if an object is a reactive proxy</li><li><code>toRaw</code> - Retrieve the original (unproxied) object from a reactive proxy</li><li><code>toRef</code> - Create a ref linked to a property on an object</li><li><code>triggerRef</code> - Manually trigger effects that depend on a ref</li><li><code>deepClone</code> - Deep-clone any value with cycle detection</li><li><code>deepToRaw</code> - Convert reactive/ref structures into plain, clone-safe data</li><li><code>traverse</code> - Recursively access every property to establish reactive deps (used internally by watch)</li><li><code>isComputed</code> - Check if a value is a computed ref</li></ul><h2 id="type-definitions" tabindex="-1">Type Definitions <a class="header-anchor" href="#type-definitions" aria-label="Permalink to &quot;Type Definitions&quot;">​</a></h2><ul><li><code>Ref&lt;T&gt;</code> - Type for ref objects</li><li><code>ComputedRef&lt;T&gt;</code> - Type for computed refs</li><li><code>WritableComputedRef&lt;T&gt;</code> - Type for writable computed refs</li><li><code>WatchSource&lt;T&gt;</code> - Type for sources that can be watched</li><li><code>WatchEffect</code> - Type for watch effect handlers</li><li><code>WatchOptions</code> - Type for watch options</li><li><code>StateEvent</code> - Type for state change events</li></ul>',10)]))}const u=t(r,[["render",c]]);export{h as __pageData,u as default};
